#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals euclidean_geometry. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Local Open Scope ring_scope. Variable R : realType. Theorem geometry_putnam_triangle_segment_product : forall (A B C P : 'rV[R]_2) (a b c d : R), ~ colinear A B C -> inside_triangle A B C P -> (exists Q R S : 'rV[R]_2, on_line Q B C /\ colinear A P Q /\ dist B Q = c /\ dist Q C = d /\ on_line R A C /\ colinear B P R /\ dist C R = a /\ dist R A = d /\ on_line S A B /\ colinear C P S /\ dist A S = b /\ dist S B = d) -> a * b * c = d ^ 3.
